import hashlib,json,sys
from pathlib import Path
sys.path.insert(0,'/private/tmp/sdkbench-product-conformance-20261121/src')
from sdkbench.candidates.applications import fixture
from sdkbench.p0 import Bundle
from sdkbench.p0.evaluators import routing
root=Path('/private/tmp/fq-native-block-products-20261122/docs/development/evidence')
index=json.loads((root/'shared-cz-synthesis-screen.json').read_text())
def read(entry):
 raw=(root/entry['name']).read_bytes();assert hashlib.sha256(raw).hexdigest()==entry['sha256'] and len(raw)==entry['bytes'];return json.loads(raw)
operations={};rows=[]
for entry in index['operation_files']:
 data=read(entry);assert not operations.keys()&data.keys()
 for key,value in data.items():assert hashlib.sha256(json.dumps(value,separators=(',',':'),allow_nan=False).encode()).hexdigest()==key
 operations.update(data)
for entry in index['row_files']:rows.extend(read(entry))
bundle=Bundle(Path('/private/tmp/sdkbench-product-conformance-20261121/docs/implementation'))
accepted=0;max_error=0
for row in rows:
 width,family,topology=row['case'];source=fixture(width,family,topology,index['manifest']['nonces'][row['nonce_index']])
 case=bundle.cases['ROUTE-GRID-08' if width==8 else f'ROUTE-LINE-{width:02d}']
 for variant in row['variants'].values():
  p=variant['payload'];key=p.pop('operations_ref');variant['payload']={'operations':operations[key],**p}
  actual=routing(variant['payload'],source,None,case,0);assert actual==variant['metrics'];assert p['final_layout']==list(range(width))
  max_error=max(max_error,actual['max_semantic_error']);accepted+=1
 if accepted%120==0:print(json.dumps({'accepted':accepted}),flush=True)
for entry in index['original_files']:
 raw=(json.dumps(rows[slice(*entry['row_range'])],separators=(',',':'),allow_nan=False)+'\n').encode()
 assert hashlib.sha256(raw).hexdigest()==entry['sha256'] and len(raw)==entry['bytes']
for module in ('flagquantum','qiskit','cirq'):assert not any(name==module or name.startswith(module+'.') for name in sys.modules)
report={'accepted':accepted,'failures':0,'maximum_semantic_residual':max_error,'SDK_imports':[],'original_report_bytes_reconstructed':True,'full_operator_acceptances':sum(row['case'][0]==6 for row in rows)*2,'three_probe_acceptances':sum(row['case'][0]!=6 for row in rows)*2,'driver_source':Path(__file__).read_text()}
(root/'shared-cz-synthesis-replay.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({k:v for k,v in report.items() if k!='driver_source'}))
